head.script:
// 가이드 : DataList 데이터 변경 성능 개선 샘플 (setBroadcast / setJSON)

/*
 * 화면 동작
 * 0. 샘플 데이터는 법인사용자등록신청 목록(dltMain, ULDSTF30700 조회 결과와 같은 21컬럼)이며 처리 건수만큼 화면에서 생성한다
 * 1. 처리 건수를 입력하고 7.1 「setBroadcast」 영역의 버튼으로 같은 건수를 세 가지 방식으로 입력해 소요시간을 비교한다
 *    - 건별 반영(비권장)     : broadcast 기본값(true) 그대로 insertRow/setCellData 를 반복 → 건마다 그리드가 갱신된다
 *    - setBroadcast 묶음(권장): dlt.setBroadcast(false) → 반복 변경 → dlt.setBroadcast(true, true) → 마지막에 한 번만 갱신
 *    - 전역 setBroadcast     : $c.data.setBroadcast(false/true) 공통함수로 화면의 모든 DataCollection 전파를 한꺼번에 제어(두 DataList 동시 입력)
 * 2. 7.2 「setJSON」 영역의 버튼으로 setJSON 호출 횟수에 따른 차이를 비교한다
 *    - 건별 setJSON(비권장)  : 행마다 setJSON(row, true) 를 반복 호출
 *    - 한 번에 setJSON(권장)  : 배열로 모아 setJSON(list) 를 1회 호출
 *    - DataMap setJSON       : 객체 리터럴로 만들어 한 번에 설정(권장 표기)
 *    - 신청 목록 추가        : 고정 샘플 3건(APPL_DATA)을 setJSON(jsonArray, true) 로 기존 신청 목록 뒤에 append
 * 3. 각 실행 결과는 하단 「실행 로그」 그리드에 (처리 방식·API·건수·소요시간) 으로 누적된다
 *
 * 담긴 패턴
 * - dataList.setBroadcast(false) / setBroadcast(true, true)   : 대량 변경 전 전파 중지, 변경 후 전파 재개 + 바인딩 컴포넌트 즉시 갱신
 * - $c.data.setBroadcast(false) / $c.data.setBroadcast(true)  : 화면 단위 일괄 제어 공통함수(내부 $p.data.setBroadcast — 여러 DataCollection 을 함께 변경할 때)
 * - dataList.setJSON(jsonArray)                               : 데이터를 한 번에 설정(기존 데이터 대체, 행 상태 R)
 * - dataList.setJSON(jsonArray, true)                         : 기존 데이터에 append
 * - dataMap.setJSON(jsonObject)                               : 객체 리터럴로 한 번에 설정
 *
 * 참고
 * - setBroadcast(true) 만 호출하면 전파는 재개되지만 이미 변경된 내용으로 컴포넌트가 다시 그려지지는 않는다.
 *   묶음 변경 뒤에는 반드시 setBroadcast(true, true) 로 refresh 까지 요청한다.
 * - 반복문 안에서 return/throw 로 빠져나가면 setBroadcast(true, true) 가 누락될 수 있으므로 try/finally 로 복원한다.
 * - 소요시간은 브라우저·데이터량에 따라 달라지며, 절대값보다 방식 간 상대 비교가 목적이다.
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "SMPDLT10000";

scwin.DEFAULT_ROW_COUNT = 2000;    // 기본 처리 건수
scwin.MAX_ROW_COUNT = 50000;       // 브라우저 보호를 위한 상한

// 법인사용자등록신청(dltMain) 샘플 코드값 — ULDSTF30700 법인사용자 조회 화면 기준
scwin.MKT_TPS = [
	{ cd : "1", nm : "유가" },
	{ cd : "2", nm : "코스닥" },
	{ cd : "3", nm : "코넥스" }
];
scwin.CORP_USR_TPS = [
	{ cd : "01", nm : "공시책임자" },
	{ cd : "02", nm : "공시담당자" },
	{ cd : "03", nm : "일반담당자" }
];
scwin.APPL_RSLTS = ["Y", "R"];    // Y:승인, R:접수

// 7.2.2 setJSON append 샘플 데이터 — 법인사용자등록신청(dltMain 구조) 고정 3건
scwin.APPL_DATA = [
	{ rowNum : "1", cnt : "3", corpUsrRegApplSeq : "900001", mktTpCd : "1", mktTpNm : "유가",
	  integUsrId : "krx_user01", isurCd : "A900001", isuSrtCd : "900001", comNm : "한국거래소",
	  corpUsrNm : "홍길동", telNo : "02-3774-9000", cellphoneNo : "010-9000-0001", email : "hong@krx.co.kr",
	  regDd : "20260901", corpUsrTpCd : "01", corpUsrTpNm : "공시책임자", applRslt : "Y",
	  fileList : "신청서_한국거래소.pdf", attachFileNm : "신청서_한국거래소.pdf", attachFileSeq : "1", apfmNo : "APFM900001" },
	{ rowNum : "2", cnt : "3", corpUsrRegApplSeq : "900002", mktTpCd : "2", mktTpNm : "코스닥",
	  integUsrId : "krx_user02", isurCd : "A900002", isuSrtCd : "900002", comNm : "코스닥상장기업",
	  corpUsrNm : "김철수", telNo : "02-3774-9001", cellphoneNo : "010-9000-0002", email : "kim@kosdaq.co.kr",
	  regDd : "20260902", corpUsrTpCd : "02", corpUsrTpNm : "공시담당자", applRslt : "R",
	  fileList : "", attachFileNm : "", attachFileSeq : "", apfmNo : "APFM900002" },
	{ rowNum : "3", cnt : "3", corpUsrRegApplSeq : "900003", mktTpCd : "3", mktTpNm : "코넥스",
	  integUsrId : "krx_user03", isurCd : "A900003", isuSrtCd : "900003", comNm : "코넥스상장기업",
	  corpUsrNm : "이영희", telNo : "02-3774-9002", cellphoneNo : "010-9000-0003", email : "lee@konex.co.kr",
	  regDd : "20260903", corpUsrTpCd : "03", corpUsrTpNm : "일반담당자", applRslt : "R",
	  fileList : "", attachFileNm : "", attachFileSeq : "", apfmNo : "APFM900003" }
];


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 10
 * @description 페이지 로드. 기본 처리 건수를 설정한다.
 * @hidden N
*/
scwin.onpageload = function () {
	try {
		dma_cond.set("rowCount", String(scwin.DEFAULT_ROW_COUNT));
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.onpageload" });
	}
};


///////// 3. 컴포넌트 이벤트 영역 /////////

// ── 7.1 setBroadcast ──

/**
 * @event
 * @name scwin.btn_insertEach_onclick
 * @description [건별 반영(비권장)] broadcast 기본값(true) 상태에서 insertRow/setCellData 를 반복한다.
 *              건마다 바인딩된 그리드가 갱신되어 건수가 커질수록 느려진다.
 * @hidden N
*/
scwin.btn_insertEach_onclick = function () {
	try {
		const totCount = scwin.getTotCount();
		if (!totCount) { return; }

		dltMain.removeAll();
		const startTime = performance.now();

		scwin.fillMainByCell(totCount);    // broadcast true — 건마다 그리드 갱신

		scwin.printLog("건별 반영(비권장)", "insertRow + setCellData", totCount, startTime, "broadcast 기본값(true) 유지");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_insertEach_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_insertBroadcast_onclick
 * @description [setBroadcast 묶음(권장)] 변경 전 setBroadcast(false) 로 전파를 멈추고,
 *              변경 후 setBroadcast(true, true) 로 전파 재개 + 바인딩 컴포넌트를 한 번만 갱신한다.
 * @hidden N
*/
scwin.btn_insertBroadcast_onclick = function () {
	try {
		const totCount = scwin.getTotCount();
		if (!totCount) { return; }

		dltMain.removeAll();
		const startTime = performance.now();

		dltMain.setBroadcast(false);    // 모든 data 변경 전 비활성화
		try {
			scwin.fillMainByCell(totCount);
		} finally {
			dltMain.setBroadcast(true, true);    // 모든 data 변경 후 활성화 + refresh (예외 시에도 복원)
		}

		scwin.printLog("setBroadcast 묶음(권장)", "setBroadcast(false) → 변경 → setBroadcast(true, true)", totCount, startTime, "마지막에 한 번만 갱신");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_insertBroadcast_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_insertGlobal_onclick
 * @description [전역 setBroadcast] $c.data.setBroadcast(false) 공통함수로 화면의 모든 DataCollection 전파를 멈추고
 *              두 DataList(법인사용자등록신청·부서)를 함께 변경한 뒤 $c.data.setBroadcast(true) 로 재개한다.
 * @hidden N
*/
scwin.btn_insertGlobal_onclick = function () {
	try {
		const totCount = scwin.getTotCount();
		if (!totCount) { return; }

		dltMain.removeAll();
		dlt_dept.removeAll();
		const startTime = performance.now();

		$c.data.setBroadcast(false);    // 화면의 모든 DataCollection 전파 중지 (공통함수 — 내부 $p.data.setBroadcast)
		try {
			scwin.fillMainByCell(totCount);
			scwin.fillDeptByCell(totCount);
		} finally {
			$c.data.setBroadcast(true);    // 최종 데이터로 연동 컴포넌트 일괄 갱신
		}

		scwin.printLog("전역 setBroadcast", "$c.data.setBroadcast(false) → 변경 → $c.data.setBroadcast(true)", totCount * 2, startTime, "신청 목록 + 부서 두 DataList 동시 변경");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_insertGlobal_onclick" });
	}
};

// ── 7.2 setJSON ──

/**
 * @event
 * @name scwin.btn_setJsonEach_onclick
 * @description [건별 setJSON(비권장)] 행마다 setJSON(row, true) 를 반복 호출한다.
 *              호출마다 데이터 반영 + 컴포넌트 갱신이 일어나 느리다.
 * @hidden N
*/
scwin.btn_setJsonEach_onclick = function () {
	try {
		const totCount = scwin.getTotCount();
		if (!totCount) { return; }

		dltMain.removeAll();
		const startTime = performance.now();

		const today = $c.date.getServerDateTime("yyyyMMdd");
		for (let i = 1; i <= totCount; i++) {
			dltMain.setJSON([scwin.makeApplRow(i, totCount, today)], true);    // 건마다 append 호출 — 비권장
		}

		scwin.printLog("건별 setJSON(비권장)", "setJSON(row, true) × N", totCount, startTime, "호출마다 반영·갱신");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_setJsonEach_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_setJsonOnce_onclick
 * @description [한 번에 setJSON(권장)] 최종 결과를 배열로 모아 setJSON(list) 를 1회만 호출한다.
 * @hidden N
*/
scwin.btn_setJsonOnce_onclick = function () {
	try {
		const totCount = scwin.getTotCount();
		if (!totCount) { return; }

		dltMain.removeAll();
		const startTime = performance.now();

		const applList = scwin.makeApplList(totCount);    // 먼저 배열로 모은다
		dltMain.setJSON(applList);                        // 한 번만 호출

		scwin.printLog("한 번에 setJSON(권장)", "setJSON(list) × 1", totCount, startTime, "배열로 모아 1회 호출");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_setJsonOnce_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_setJsonBasic_onclick
 * @description [DataMap setJSON] 키를 하나씩 대입하지 않고 객체 리터럴로 만들어 setJSON 한 번으로 설정한다(권장 표기).
 * @hidden N
*/
scwin.btn_setJsonBasic_onclick = function () {
	try {
		const startTime = performance.now();

		// 권장 : 객체 리터럴로 한 번에 구성 → setJSON 1회
		const basicData = {
			name      : "WebSquare",
			address   : "서울시 구로구",
			telephone : "01011112222"
		};
		dma_basic.setJSON(basicData);

		scwin.printLog("DataMap setJSON", "dataMap.setJSON(object)", 1, startTime, "객체 리터럴로 한 번에 설정");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_setJsonBasic_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_appendAppl_onclick
 * @description [setJSON append] 고정 샘플 3건을 기존 신청 목록(dltMain) 뒤에 추가한다(append = true). 기존 행은 유지된다.
 * @hidden N
*/
scwin.btn_appendAppl_onclick = function () {
	try {
		const startTime = performance.now();

		scwin.appendApplData(dltMain);

		scwin.printLog("setJSON append", "setJSON(jsonArray, true)", scwin.APPL_DATA.length, startTime, "기존 데이터 뒤에 추가 (누적 " + dltMain.getRowCount() + "건)");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_appendAppl_onclick" });
	}
};

// ── 공통 ──

/**
 * @event
 * @name scwin.btn_clearData_onclick
 * @description 샘플 데이터(신청 목록·부서·기본정보)를 모두 비운다.
 * @hidden N
*/
scwin.btn_clearData_onclick = function () {
	try {
		dltMain.removeAll();
		dlt_dept.removeAll();
		dma_basic.reset();
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_clearData_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_clearLog_onclick
 * @description 실행 로그를 비운다.
 * @hidden N
*/
scwin.btn_clearLog_onclick = function () {
	try {
		dlt_log.removeAll();
	} catch (ex) {
		$c.exception.handleError(ex, { context : "SMPDLT10000.btn_clearLog_onclick" });
	}
};


///////// 4. 서브미션 콜백 영역 /////////


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.getTotCount
 * @description 처리 건수 입력값을 검증해 숫자로 돌려준다. 잘못된 값이면 안내 후 0 을 반환한다.
 * @returns {Number} 처리 건수 (검증 실패 시 0)
 * @hidden N
*/
scwin.getTotCount = function () {
	const totCount = Number(dma_cond.get("rowCount"));

	if (!Number.isInteger(totCount) || totCount < 1) {
		$c.win.alert("처리 건수는 1 이상의 정수로 입력하세요.");
		ipt_rowCount.focus();
		return 0;
	}
	if (totCount > scwin.MAX_ROW_COUNT) {
		$c.win.alert("처리 건수는 최대 " + $c.num.formatNumber(scwin.MAX_ROW_COUNT) + "건까지 입력할 수 있습니다.");
		ipt_rowCount.focus();
		return 0;
	}
	return totCount;
};

/**
 * @method
 * @name scwin.makeApplRow
 * @description 법인사용자등록신청(dltMain) 샘플 1행을 만든다. 컬럼 구성은 ULDSTF30700 조회 결과와 같다.
 * @param {Number} i 순번(1부터)
 * @param {Number} totCount 전체 건수(조회건수 컬럼)
 * @param {String} today 등록일자로 쓸 오늘 날짜(yyyyMMdd)
 * @returns {Object} 법인사용자등록신청 행 객체
 * @hidden N
*/
scwin.makeApplRow = function (i, totCount, today) {
	const seq = String(i).padStart(6, "0");
	const mktTp = scwin.MKT_TPS[i % scwin.MKT_TPS.length];
	const corpUsrTp = scwin.CORP_USR_TPS[i % scwin.CORP_USR_TPS.length];
	const hasFile = i % 4 === 0;    // 4건 중 1건은 첨부파일 보유

	return {
		rowNum            : String(i),
		cnt               : String(totCount),
		corpUsrRegApplSeq : seq,
		mktTpCd           : mktTp.cd,
		mktTpNm           : mktTp.nm,
		integUsrId        : "user" + seq,
		isurCd            : "A" + seq,
		isuSrtCd          : seq,
		comNm             : "샘플회사" + i,
		corpUsrNm         : "담당자" + i,
		telNo             : "02-1234-" + String(i % 10000).padStart(4, "0"),
		cellphoneNo       : "010-1234-" + String(i % 10000).padStart(4, "0"),
		email             : "user" + seq + "@sample.co.kr",
		regDd             : today,
		corpUsrTpCd       : corpUsrTp.cd,
		corpUsrTpNm       : corpUsrTp.nm,
		applRslt          : scwin.APPL_RSLTS[i % scwin.APPL_RSLTS.length],
		fileList          : hasFile ? "신청서" + i + ".pdf" : "",
		attachFileNm      : hasFile ? "신청서" + i + ".pdf" : "",
		attachFileSeq     : hasFile ? "1" : "",
		apfmNo            : "APFM" + seq
	};
};

/**
 * @method
 * @name scwin.makeApplList
 * @description 법인사용자등록신청 샘플 n행을 배열로 만든다(setJSON 1회 호출용).
 * @param {Number} totCount 생성 건수
 * @returns {Array} 법인사용자등록신청 행 배열
 * @hidden N
*/
scwin.makeApplList = function (totCount) {
	const today = $c.date.getServerDateTime("yyyyMMdd");
	const list = [];
	for (let i = 1; i <= totCount; i++) {
		list.push(scwin.makeApplRow(i, totCount, today));
	}
	return list;
};

/**
 * @method
 * @name scwin.fillMainByCell
 * @description 법인사용자등록신청 DataList(dltMain) 에 insertRow + setCellData 로 n행을 건별 입력한다.
 *              행마다 21개 컬럼을 셀 단위로 설정하므로 건수 × 컬럼수만큼 변경 이벤트가 발생한다.
 *              broadcast 제어는 호출자가 담당한다(7.1 세 방식이 같은 본문을 공유).
 * @param {Number} totCount 입력 건수
 * @hidden N
*/
scwin.fillMainByCell = function (totCount) {
	const today = $c.date.getServerDateTime("yyyyMMdd");
	for (let i = 1; i <= totCount; i++) {
		const row = scwin.makeApplRow(i, totCount, today);
		const idx = dltMain.insertRow();
		Object.keys(row).forEach(function (colId) {
			dltMain.setCellData(idx, colId, row[colId]);    // 셀 단위 설정 — 컬럼마다 변경 이벤트 발생
		});
	}
};

/**
 * @method
 * @name scwin.fillDeptByCell
 * @description 부서 DataList 에 insertRow + setCellData 로 n행을 건별 입력한다(전역 setBroadcast 시연용 두 번째 DataList).
 * @param {Number} totCount 입력 건수
 * @hidden N
*/
scwin.fillDeptByCell = function (totCount) {
	for (let i = 1; i <= totCount; i++) {
		const idx = dlt_dept.insertRow();
		dlt_dept.setCellData(idx, "DEPT_CD", "D" + String(i).padStart(5, "0"));
		dlt_dept.setCellData(idx, "DEPT_NM", "부서" + i);
		dlt_dept.setCellData(idx, "EMP_CNT", String(i % 50));
	}
};

/**
 * @method
 * @name scwin.appendApplData
 * @description 고정 샘플 3건을 대상 DataList 의 기존 데이터 뒤에 추가한다(7.2.2 setJSON append 샘플).
 *              여러 행을 추가할 때 행마다 setJSON 을 부르지 않고 배열로 모아 한 번만 호출한다.
 * @param {Object} dsObj 대상 DataList (dltMain 구조)
 * @hidden N
*/
scwin.appendApplData = function (dsObj) {
	dsObj.setJSON(scwin.APPL_DATA, true);    // append = true : 기존 데이터 유지 + 추가
};

/**
 * @method
 * @name scwin.printLog
 * @description 실행 결과(처리 방식·API·건수·소요시간)를 로그 DataList 에 1행 추가한다.
 * @param {String} caseNm 처리 방식
 * @param {String} apiNm 사용 API
 * @param {Number} rowCnt 처리 건수
 * @param {Number} startTime 시작 시각(performance.now())
 * @param {String} note 비고
 * @hidden N
*/
scwin.printLog = function (caseNm, apiNm, rowCnt, startTime, note) {
	const elapsed = Math.round(performance.now() - startTime);
	const logRow = {
		seq     : String(dlt_log.getRowCount() + 1),
		caseNm  : caseNm,
		apiNm   : apiNm,
		rowCnt  : $c.num.formatNumber(rowCnt),
		elapsed : $c.num.formatNumber(elapsed),
		note    : note || ""
	};
	dlt_log.setJSON([logRow], true);
};
